        Legacy open-loop evaporative cooling towers installed atop an enterprise facility in Mesa, Arizona. Hyperscalers are replacing this water-intensive infrastructure with sealed closed-loop dry coolers. Photo by Rsparks3 via <a href="https://commons.wikimedia.org/wiki/File:Data_center_cooling_tower.jpg" target="_blank" rel="noopener">Wikimedia Commons (CC0 1.0)</a>.
      </figcaption>
    </figure>

    <!-- Native Cloudflare Pages D1 Newsletter Subscription Form -->
    <section class="newsletter-card">
      <h2>Stay Ahead of Global Compute Infrastructure Mandates</h2>
      <p>Receive regulatory updates, FERC docket summaries, and engineering breakthroughs delivered directly from our research database.</p>

      <form class="newsletter-form" id="newsletter-form">
        <input type="hidden" name="source" value="index_hero">
        <input type="email" id="subscriber-email" name="email" placeholder="Enter your work email" required aria-label="Email address">
        <button type="submit" class="btn-primary" id="subscribe-btn">Subscribe</button>
      </form>
      <div class="form-feedback" id="form-msg" style="display: none;"></div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container" style="display: flex; justify-content: space-between; flex-wrap: wrap; gap: 2rem;">
      <div>
        <p><strong>GreenCompute DB</strong> — Independent Research on Sustainable Digital Infrastructure</p>
        <p>Statutes, engineering filings, and regulatory dockets updated continuously.</p>
      </div>
      <div>
        <p><a href="sources.html" style="color: var(--primary);">Primary Source Repository</a> | <a href="sitemap.xml" style="color: var(--primary);">XML Sitemap</a> | <a href="feed.xml" style="color: var(--primary);">RSS Feed</a></p>
      </div>
    </div>
  </footer>

  <script>
    // Theme Engine (Dark/Light Mode)
    const themeBtn = document.getElementById('theme-btn');
    const htmlEl = document.documentElement;
    const currentTheme = localStorage.getItem('theme') || (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
    htmlEl.setAttribute('data-theme', currentTheme);

    themeBtn.addEventListener('click', () => {
      const nextTheme = htmlEl.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
      htmlEl.setAttribute('data-theme', nextTheme);
      localStorage.setItem('theme', nextTheme);
    });

    // Cloudflare D1 Native Subscription Handler
    const form = document.getElementById('newsletter-form');
    const msgEl = document.getElementById('form-msg');
    const btn = document.getElementById('subscribe-btn');

    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      btn.disabled = true;
      btn.innerText = 'Submitting...';
      msgEl.style.display = 'none';

      try {
        const res = await fetch('/api/subscribe', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ email: document.getElementById('subscriber-email').value, source: 'index' })
        });
        const data = await res.json();
        msgEl.style.display = 'block';
        msgEl.style.color = data.success ? 'var(--accent-green)' : 'red';
        msgEl.innerText = data.message;
        if (data.success) form.reset();
      } catch (err) {
        msgEl.style.display = 'block';
        msgEl.style.color = 'red';
        msgEl.innerText = 'Network error. Please try again.';
      } finally {
        btn.disabled = false;
        btn.innerText = 'Subscribe';
      }
    });

    // Quick Search Client Filter
    document.getElementById('quick-search').addEventListener('input', (e) => {
      const query = e.target.value.toLowerCase();
      document.querySelectorAll('#searchable-cards article').forEach(card => {
        card.style.display = card.innerText.toLowerCase().includes(query) ? 'block' : 'none';
      });
    });
  </script>
</body>
</html>

