def create_project_zip(output_filename="greencompute-site.zip"):
    print(f"Building {output_filename}...")
    with zipfile.ZipFile(output_filename, 'w', zipfile.ZIP_DEFLATED) as zipf:
        for file_path, content in FILES.items():
