    # Root worker: Supported natively by Drag & Drop to handle /api/subscribe and static assets
    "_worker.js": """export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname === "/api/subscribe" && request.method === "POST") {
      try {
        const contentType = request.headers.get("content-type") || "";
        let email = "";
        let sourcePage = "index";

        if (contentType.includes("application/json")) {
          const data = await request.json();
          email = data.email?.trim().toLowerCase();
          sourcePage = data.source || "index";
        } else if (contentType.includes("application/x-www-form-urlencoded")) {
          const formData = await request.formData();
          email = formData.get("email")?.toString().trim().toLowerCase();
          sourcePage = formData.get("source")?.toString() || "index";
        }

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!email || !emailRegex.test(email)) {
          return new Response(
            JSON.stringify({ success: false, message: "Please provide a valid email address." }),
            { status: 400, headers: { "Content-Type": "application/json" } }
          );
        }

        if (env.DB) {
          const statement = env.DB.prepare(
            "INSERT OR IGNORE INTO subscribers (email, source_page) VALUES (?, ?)"
          ).bind(email, sourcePage);
          const result = await statement.run();
          return new Response(
            JSON.stringify({
              success: true,
              message: result.meta?.changes > 0 
                ? "Thank you for subscribing to sustainable infrastructure updates." 
                : "You are already subscribed to updates."
            }),
            { status: 200, headers: { "Content-Type": "application/json" } }
          );
        }

        return new Response(
          JSON.stringify({ success: true, message: "Thank you for subscribing!" }),
          { status: 200, headers: { "Content-Type": "application/json" } }
        );
      } catch (error) {
        return new Response(
          JSON.stringify({ success: false, message: "A server error occurred. Please try again later." }),
          { status: 500, headers: { "Content-Type": "application/json" } }
        );
      }
    }

    return env.ASSETS.fetch(request);
  }
};
