figure { margin: 2rem 0; background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: var(--radius); overflow: hidden; }
figure img { width: 100%; max-height: 450px; object-fit: cover; display: block; }
figcaption { padding: 0.75rem 1rem; font-size: 0.85rem; color: var(--text-muted); border-top: 1px solid var(--border-color); }

.newsletter-card { background: var(--bg-surface); border: 2px solid var(--primary); border-radius: var(--radius); padding: 2.5rem; margin: 3rem 0; text-align: center; }
.newsletter-form { display: flex; gap: 0.5rem; max-width: 500px; margin: 1.5rem auto 0; flex-direction: column; }
@media (min-width: 540px) { .newsletter-form { flex-direction: row; } }
.newsletter-form input[type="email"] { flex-grow: 1; padding: 0.75rem 1rem; border: 1px solid var(--border-color); border-radius: var(--radius); background: var(--bg-primary); color: var(--text-main); font-size: 1rem; }
.btn-primary { padding: 0.75rem 1.5rem; background: var(--primary); color: #fff; border: none; border-radius: var(--radius); font-weight: 600; cursor: pointer; }
.btn-primary:hover { background: var(--primary-hover); }

.calc-wrapper { background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: var(--radius); padding: 2rem; margin: 2rem 0; }
.slider-group { margin-bottom: 1.5rem; }
.slider-group label { display: flex; justify-content: space-between; font-weight: 600; margin-bottom: 0.5rem; }
input[type="range"] { width: 100%; }
.calc-results { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 1rem; margin-top: 1.5rem; padding-top: 1.5rem; border-top: 1px solid var(--border-color); }
.stat-box { background: var(--bg-subtle); padding: 1rem; border-radius: var(--radius); text-align: center; }
.stat-box .number { font-size: 1.75rem; font-weight: 700; color: var(--primary); display: block; }

footer.site-footer { background: var(--bg-surface); border-top: 1px solid var(--border-color); padding: 3rem 0; color: var(--text-muted); font-size: 0.9rem; }
