    "styles.css": """:root {
  --font-serif: "Charter", "Bitstream Charter", "Sitka Text", Cambria, Georgia, serif;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: ui-monospace, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;

  --bg-canvas: #fcfcfc;
  --bg-surface: #ffffff;
  --bg-subtle: #f4f4f5;
  --bg-accent: #f0fdf4;

  --border-color: #e4e4e7;
  --border-dark: #27272a;

  --text-main: #18181b;
  --text-muted: #52525b;
  --text-faint: #71717a;

  --primary: #046a38;
  --primary-hover: #03542c;
  --brand-navy: #0f172a;
  --accent-amber: #92400e;

  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.07);
}

[data-theme="dark"] {
  --bg-canvas: #09090b;
  --bg-surface: #121215;
  --bg-subtle: #18181b;
  --bg-accent: #052e16;

  --border-color: #27272a;
  --border-dark: #e4e4e7;

  --text-main: #f4f4f5;
  --text-muted: #a1a1aa;
  --text-faint: #71717a;

  --primary: #22c55e;
  --primary-hover: #4ade80;
  --brand-navy: #38bdf8;
  --accent-amber: #f59e0b;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font-sans);
  background-color: var(--bg-canvas);
  color: var(--text-main);
  line-height: 1.68;
  font-size: 1.05rem;
  -webkit-font-smoothing: antialiased;
}

.container {
  width: 100%;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Editorial Masthead */
header.masthead {
  border-bottom: 1px solid var(--border-color);
  background-color: var(--bg-surface);
  position: sticky;
  top: 0;
  z-index: 100;
}

.masthead-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 0;
}

.brand {
  font-family: var(--font-serif);
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--text-main);
  text-decoration: none;
  letter-spacing: -0.01em;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.brand-tag {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  text-transform: uppercase;
  background: var(--bg-subtle);
  padding: 0.15rem 0.45rem;
  border-radius: 3px;
  color: var(--text-muted);
  border: 1px solid var(--border-color);
}

nav.main-nav ul {
  display: flex;
  list-style: none;
  gap: 1.5rem;
  align-items: center;
}

nav.main-nav a {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.92rem;
  font-weight: 500;
  transition: color 0.15s ease;
}

nav.main-nav a:hover, nav.main-nav a.active {
  color: var(--text-main);
  font-weight: 600;
}

.theme-toggle-btn {
  background: none;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  color: var(--text-muted);
  cursor: pointer;
  padding: 0.35rem 0.65rem;
  font-size: 0.8rem;
  font-family: var(--font-mono);
}

/* Typography & Editorial Accents */
h1, h2, h3, h4 {
  font-family: var(--font-serif);
  color: var(--text-main);
  line-height: 1.25;
  letter-spacing: -0.015em;
}

h1 {
  font-size: clamp(2.2rem, 3.8vw, 3.1rem);
  font-weight: 700;
  margin-top: 1rem;
  margin-bottom: 1.25rem;
}

h2 {
  font-size: 1.85rem;
  font-weight: 700;
  margin: 3rem 0 1.25rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--border-color);
}

h3 {
  font-size: 1.35rem;
  font-weight: 600;
  margin: 2rem 0 0.75rem;
}

p {
  margin-bottom: 1.35rem;
}

.lead {
  font-size: 1.25rem;
  line-height: 1.6;
  color: var(--text-muted);
  margin-bottom: 2rem;
  font-family: var(--font-serif);
}

/* Badges & Meta */
.badge {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 0.2rem 0.5rem;
  border-radius: 3px;
  border: 1px solid transparent;
}

.badge-green { background: #dcfce7; color: #14532d; border-color: #bbf7d0; }
.badge-blue { background: #e0f2fe; color: #075985; border-color: #bae6fd; }
.badge-amber { background: #fef3c7; color: #78350f; border-color: #fde68a; }

[data-theme="dark"] .badge-green { background: #052e16; color: #86efac; border-color: #14532d; }
[data-theme="dark"] .badge-blue { background: #082f49; color: #7dd3fc; border-color: #0c4a6e; }
[data-theme="dark"] .badge-amber { background: #451a03; color: #fde68a; border-color: #78350f; }

/* Callout Quotes */
.statute-quote {
  border-left: 3px solid var(--primary);
  background: var(--bg-subtle);
  padding: 1.25rem 1.75rem;
  margin: 1.75rem 0;
  font-family: var(--font-serif);
  font-style: italic;
  color: var(--text-main);
}

.statute-cite {
  display: block;
  font-family: var(--font-mono);
  font-style: normal;
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-top: 0.75rem;
}

/* Institutional Tables */
.table-wrap {
  overflow-x: auto;
  margin: 2rem 0 2.5rem;
  border: 1px solid var(--border-color);
  background: var(--bg-surface);
}

table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
}

th, td {
  padding: 0.85rem 1.15rem;
  border-bottom: 1px solid var(--border-color);
  vertical-align: top;
}

th {
  font-family: var(--font-mono);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  background-color: var(--bg-subtle);
  color: var(--text-muted);
}

tbody tr:hover {
  background-color: var(--bg-subtle);
}

/* Figures & Real Photography */
figure.media-figure {
  margin: 2.5rem 0;
  border: 1px solid var(--border-color);
  background: var(--bg-surface);
}

figure.media-figure img {
  width: 100%;
  height: auto;
  max-height: 480px;
  object-fit: cover;
  display: block;
}

figcaption.media-caption {
  padding: 0.85rem 1.25rem;
  font-size: 0.86rem;
  color: var(--text-muted);
  border-top: 1px solid var(--border-color);
  background: var(--bg-surface);
  line-height: 1.5;
}

figcaption.media-caption a {
  color: var(--text-main);
  text-decoration: underline;
}

/* Cards & Layout Grid */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 1.75rem;
  margin: 2rem 0;
}

.article-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  padding: 1.75rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

/* Interactive Calculator */
.tool-box {
  border: 1px solid var(--border-color);
  background: var(--bg-surface);
  padding: 2.25rem;
  margin: 2.5rem 0;
}

.slider-unit {
  margin-bottom: 1.5rem;
}

.slider-unit label {
  display: flex;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 0.9rem;
  margin-bottom: 0.5rem;
  font-weight: 600;
}

input[type="range"] {
  width: 100%;
  accent-color: var(--primary);
}

.tool-metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1.25rem;
  border-top: 1px solid var(--border-color);
  padding-top: 1.5rem;
  margin-top: 1.5rem;
}

.metric-card {
  background: var(--bg-subtle);
  padding: 1.25rem;
  border-left: 2px solid var(--primary);
}

.metric-num {
  font-family: var(--font-mono);
  font-size: 1.85rem;
  font-weight: 700;
  color: var(--text-main);
  display: block;
}

.metric-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
}

/* Institutional Form */
.signup-box {
  background: var(--bg-subtle);
  border: 1px solid var(--border-color);
  padding: 2.5rem;
  margin: 3.5rem 0;
}

.signup-flex {
  display: flex;
  gap: 0.5rem;
  max-width: 520px;
  margin-top: 1.25rem;
}

.signup-input {
  flex-grow: 1;
  padding: 0.75rem 1rem;
  border: 1px solid var(--border-color);
  background: var(--bg-surface);
  color: var(--text-main);
  font-size: 0.95rem;
}

.signup-btn {
  padding: 0.75rem 1.5rem;
  background: var(--primary);
  color: #ffffff;
  border: none;
  font-weight: 600;
  cursor: pointer;
  font-size: 0.95rem;
  font-family: var(--font-sans);
}

.signup-btn:hover {
  background: var(--primary-hover);
}

/* Footer */
footer.mastfoot {
  border-top: 1px solid var(--border-color);
  background: var(--bg-surface);
  padding: 3rem 0;
  margin-top: 4rem;
  font-size: 0.88rem;
  color: var(--text-muted);
}
