    "index.html": """<!DOCTYPE html>
<html lang="en" data-theme="light">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>GreenCompute Research: Global Decarbonized & Closed-Loop Infrastructure</title>
  <meta name="description" content="Independent multidisciplinary research benchmark examining zero-water closed-loop cooled and 100% renewable hyperscale data centers worldwide.">
  <link rel="canonical" href="https://sustainable-dc.pages.dev/">
  <link rel="stylesheet" href="styles.css">
</head>
<body>

  <header class="masthead">
    <div class="container masthead-inner">
      <a href="index.html" class="brand">
        GreenCompute DB
        <span class="brand-tag">Research Index</span>
      </a>
      <nav class="main-nav">
        <ul>
          <li><a href="facilities.html">Facilities</a></li>
