def create_project_zip(output_filename="greencompute-site.zip"):
    print(f"Building publication-grade {output_filename}...")
    with zipfile.ZipFile(output_filename, 'w', zipfile.ZIP_DEFLATED) as zipf:
        for file_path, content in FILES.items():
            zipf.writestr(file_path, content.strip())
            print(f"  [+] Packed: {file_path}")
    print(f"\nDone! '{output_filename}' generated with unabridged research and images.")

if __name__ == "__main__":
    create_project_zip()

