p { margin-bottom: 1.35rem; }
.lead { font-size: 1.25rem; line-height: 1.6; color: var(--text-muted); margin-bottom: 2rem; font-family: var(--font-serif); }

.badge { font-family: var(--font-mono); font-size: 0.75rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; padding: 0.2rem 0.5rem; border-radius: 3px; border: 1px solid transparent; }
.badge-green { background: #dcfce7; color: #14532d; border-color: #bbf7d0; }
.badge-blue { background: #e0f2fe; color: #075985; border-color: #bae6fd; }
.badge-amber { background: #fef3c7; color: #78350f; border-color: #fde68a; }

[data-theme="dark"] .badge-green { background: #052e16; color: #86efac; border-color: #14532d; }
[data-theme="dark"] .badge-blue { background: #082f49; color: #7dd3fc; border-color: #0c4a6e; }
[data-theme="dark"] .badge-amber { background: #451a03; color: #fde68a; border-color: #78350f; }

.table-wrap { overflow-x: auto; margin: 2rem 0 2.5rem; border: 1px solid var(--border-color); background: var(--bg-surface); }
table { width: 100%; border-collapse: collapse; text-align: left; font-size: 0.95rem; }
th, td { padding: 0.85rem 1.15rem; border-bottom: 1px solid var(--border-color); vertical-align: top; }
th { font-family: var(--font-mono); font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.03em; background-color: var(--bg-subtle); color: var(--text-muted); }
tbody tr:hover { background-color: var(--bg-subtle); }

